// Segredo compartilhado com o Worker do Cloudflare (env N8N_NOTION_WEBHOOK_SECRET).
// Troque 'TROQUE_PELO_SEGREDO' pelo mesmo valor configurado no Worker (e no 07).
const SECRET = 'TROQUE_PELO_SEGREDO';

const item = $input.first().json || {};
const headers = item.headers || {};

const headerName = Object.keys(headers).find((k) => k.toLowerCase() === 'x-radar-secret');
if (!headerName || headers[headerName] !== SECRET) {
  throw new Error('x-radar-secret invalido ou ausente');
}

return [{ json: { ok: true } }];

// Lê as páginas do database "Radar Mobiliza PE" (dado cru da API do Notion) e
// normaliza para as mesmas chaves usadas no envio (07/EncaminhamentoForm).

const plainText = (arr) =>
  Array.isArray(arr) ? arr.map((t) => (t && t.plain_text) || '').join('') : '';

const valueOf = (prop) => {
  if (!prop) return '';
  const type = prop.type;
  if (type === 'title' || type === 'rich_text') return plainText(prop[type]);
  if (type === 'select') return (prop.select && prop.select.name) || '';
  if (type === 'status') return (prop.status && prop.status.name) || '';
  if (type === 'phone_number') return prop.phone_number || '';
  if (type === 'date') return (prop.date && prop.date.start) || '';
  if (type === 'url') return prop.url || '';
  if (type === 'people')
    return ((prop.people || []).map((p) => (p && p.name) || '').filter(Boolean)).join(', ');
  return '';
};

const peopleIdsOf = (prop) => {
  if (!prop || prop.type !== 'people') return [];
  return (prop.people || [])
    .map((p) => (p && p.id) || '')
    .filter((id) => id && id.length > 0);
};

const pages = $input.all()
  .map(({ json }) => json)
  .filter((p) => p && !p.archived);

const rows = pages.map((page) => {
  const props = page.properties || {};
  const tituloProp = Object.values(props).find((p) => p && p.type === 'title');
  const g = (name) => valueOf(props[name]);
  return {
    page_id: page.id,
    url: page.url || '',
    titulo: plainText((tituloProp && tituloProp.title) || []) || 'Sem título',
    o_que_disse: g('O que a pessoa disse'),
    area: g('Área'),
    precisa_retorno: g('Precisa de retorno'),
    responsavel: g('Responsável pelo contato'),
    responsavel_id: (peopleIdsOf(props['Responsável pelo contato'])[0] || ''),
    pessoa: g('Pessoa'),
    telefone: g('Telefone'),
    data: g('Data'),
    urgencia: g('Urgência'),
    o_que_fizemos: g('O que a gente fez'),
    status: g('Status'),
    fonte: g('Fonte'),
    cidade: g('Cidade'),
    sessao_responsavel: g('Sessão responsável pelo contato'),
  };
});

return [{ json: { rows } }];
